The following trivial patch seems to work around the issue but we need to implement proper parsing for GraalVM/Mandrel for JDK >= 25.

```diff
diff --git a/core/deployment/src/main/java/io/quarkus/deployment/pkg/steps/GraalVM.java b/core/deployment/src/main/java/io/quarkus/deployment/pkg/steps/GraalVM.java
index 1da4ecacd7d..24ce617573f 100644
--- a/core/deployment/src/main/java/io/quarkus/deployment/pkg/steps/GraalVM.java
+++ b/core/deployment/src/main/java/io/quarkus/deployment/pkg/steps/GraalVM.java
@@ -152,7 +152,7 @@ private static String graalVersion(String buildInfo, int jdkFeature) {
             if (versMatcher.find()) {
                 return matchVersion(version);
             } else {
-                return Version.GRAAL_MAPPING.get(Integer.toString(jdkFeature));
+                return Version.GRAAL_MAPPING.getOrDefault(Integer.toString(jdkFeature), Integer.toString(jdkFeature));
             }
         }

diff --git a/core/runtime/src/main/java/io/quarkus/runtime/graal/GraalVM.java b/core/runtime/src/main/java/io/quarkus/runtime/graal/GraalVM.java
index a5852e74a7b..26411308b3f 100644
--- a/core/runtime/src/main/java/io/quarkus/runtime/graal/GraalVM.java
+++ b/core/runtime/src/main/java/io/quarkus/runtime/graal/GraalVM.java
@@ -49,7 +49,7 @@ static Version parse(String value) {
                 if (GRAALVM_CE_VERS_PREFIX.equals(vendor) || ORACLE_GRAALVM_VERS_PREFIX.equals(vendor)) {
                     String version = versionMatcher.group(VERSION_GROUP);
                     String jdkFeature = version.split("\\.", 2)[0];
-                    return new Version(value, Version.GRAAL_MAPPING.get(jdkFeature), Distribution.GRAALVM);
+                    return new Version(value, Version.GRAAL_MAPPING.getOrDefault(jdkFeature, jdkFeature), Distribution.GRAALVM);
                 } else if (LIBERICA_NIK_VERS_PREFIX.equals(vendor)) {
